module tb(output reg done);

    logic wclk, wrst_n, wvalid, wready;
    logic [7:0] wdata;
    logic rclk, rrst_n, rready, rvalid;
    logic [7:0] rdata;

    top_module dut (
        .wclk(wclk), .wrst_n(wrst_n), .wvalid(wvalid), .wdata(wdata), .wready(wready),
        .rclk(rclk), .rrst_n(rrst_n), .rready(rready), .rvalid(rvalid), .rdata(rdata)
    );

    // independent clocks
    initial wclk = 0;
    always #5 wclk = ~wclk;   // 100MHz
    initial rclk = 0;
    always #7 rclk = ~rclk;   // ~71MHz

    int wcnt, rcnt;

    // Drive wvalid/wdata away from the wclk active edge (negedge).
    task automatic wpush(input [7:0] d);
        @(negedge wclk);
        wvalid = 1; wdata = d;
        // wait until accepted: sample pre-edge wvalid&&wready
        do @(posedge wclk); while (!(wvalid && wready));
        @(negedge wclk);
        wvalid = 0;
        wcnt++;
    endtask

    task automatic rpop(input [7:0] exp);
        @(negedge rclk);
        rready = 1;
        do @(posedge rclk); while (!(rvalid && rready));
        @(negedge rclk);
        rready = 0;
        if (rdata !== exp) begin
            $display("FAIL: rdata=%h exp=%h", rdata, exp);
            $fatal(1, "data mismatch");
        end
        rcnt++;
    endtask

    initial begin
        done = 0;
        wvalid = 0; wdata = 0; rready = 0;
        wrst_n = 0; rrst_n = 0;
        repeat (5) @(posedge wclk);
        repeat (5) @(posedge rclk);
        @(negedge wclk); wrst_n = 1;
        @(negedge rclk); rrst_n = 1;
        // wait for sync release
        repeat (5) @(posedge wclk);
        repeat (5) @(posedge rclk);

        // empty check
        if (rvalid !== 0) $fatal(1, "rvalid not 0 after reset");
        if (rdata !== 0) $fatal(1, "rdata not 0 when empty");

        // push 4, pop 4, verify order
        wpush(8'h11);
        wpush(8'h22);
        wpush(8'h33);
        wpush(8'h44);
        rpop(8'h11);
        rpop(8'h22);
        rpop(8'h33);
        rpop(8'h44);

        // wrap test: push 6, pop 6
        wpush(8'hA1);
        wpush(8'hA2);
        wpush(8'hA3);
        wpush(8'hA4);
        wpush(8'hA5);
        wpush(8'hA6);
        rpop(8'hA1);
        rpop(8'hA2);
        rpop(8'hA3);
        rpop(8'hA4);
        rpop(8'hA5);
        rpop(8'hA6);

        // full/empty boundary: fill to full, verify wready drops
        wpush(8'hB1);
        wpush(8'hB2);
        wpush(8'hB3);
        wpush(8'hB4);
        // now full; wready should be 0
        repeat (3) @(posedge wclk);
        if (wready !== 0) $fatal(1, "wready not 0 when full");
        // drain
        rpop(8'hB1);
        rpop(8'hB2);
        rpop(8'hB3);
        rpop(8'hB4);

        repeat (3) @(posedge rclk);
        if (rvalid !== 0) $fatal(1, "rvalid not 0 after drain");

        $display("PASS: wcnt=%0d rcnt=%0d", wcnt, rcnt);
        done = 1;
    end

endmodule
